import {blankIntent,type Intent,type State,type Trip,type Offer,type PreferenceDimension,type StarterSelectedOffer,type StarterRoundTripCombo,type StarterSuggestedItinerary,type SeatSelection,type SeatCabin,type SeatPosition,type SeatZone,type LotusmilesAppliedRedemption} from '@/lib/model';
