const starter=state?.starter;const starterDraft=starter?.draft||{};const starterOutbound=starter?.selectedOutboundOffer||starter?.selectedOffer||null,starterReturn=starter?.selectedReturnOffer||null,starterSelected=starterOutbound;const starterEffectiveStart=starterDraft.start||starterOutbound?.departureDate||'',starterEffectiveEnd=starterDraft.end||starterReturn?.departureDate||(starter?.tripMode==='one-way'?starterEffectiveStart:'');const starterReady=!!(starterDraft.from&&starterDraft.to&&starterEffectiveStart&&starterEffectiveEnd);const starterMissing=[(!starterDraft.from||!starterDraft.to)?tr('route','tuyến bay'):null,(!starterEffectiveStart||!starterEffectiveEnd)?tr('travel window','khoảng ngày'):null].filter(Boolean) as string[];const starterPassengers=starterDraft.passengers??1,starterBaggage=starterDraft.baggage??state?.profile.baggage??23,starterTransit=starterDraft.transit??24,starterSeat=starterDraft.seat||state?.profile.seat||'No preference',starterBudget=typeof starterDraft.budget==='number'?starterDraft.budget:100000;const starterSearch=starter?.lastSearch,starterCombos=starter?.roundTripCombos||[],starterHasCheckout=starter?.checkoutStage==='offer-payment';const starterLotusOffer=state?.profile.member&&starterCombos.length===0&&starterSearch?.leg!=='return'&&starter?.tripMode!=='round-trip'?starterSearch?.offers?.find(o=>!!buildLotusmilesBusinessUpgrade(state.profile,{passengers:starterPassengers,flexibility:o.flexibility,baseItineraryId:o.offerId,directions:1}))||null:null;const starterLotusCombo=state?.profile.member?starterCombos.find(c=>!!buildLotusmilesBusinessUpgrade(state.profile,{passengers:starterPassengers,flexibility:`${c.outbound.flexibility||''} / ${c.return.flexibility||''}`,baseItineraryId:c.id,directions:2}))||null:null;
const bookingFrom=bookingSource==='starter'?(starterDraft.from||''):trip?.from||'',bookingTo=bookingSource==='starter'?(starterDraft.to||''):trip?.to||'',bookingStart=bookingSource==='starter'?starterEffectiveStart:trip?.start||'',bookingEnd=bookingSource==='starter'?starterEffectiveEnd:trip?.end||'',bookingPassengerCount=bookingSource==='starter'?starterPassengers:trip?.passengers||0,bookingSeatPreference=bookingSource==='starter'?starterSeat:trip?.seat||state?.profile.seat||'No preference';
const bookingBaseCash=bookingItinerary?.totalPriceAUD??offer?.price??0,bookingCashTotal=bookingBaseCash+(bookingLotusmiles?.cashTaxesAUD||0)+(bag&&!bookingLotusmiles?65*bookingPassengerCount:0);
const activeSeatSelection=seatSelections[activeSeatPassenger]||null,activeRecommendedSeat=recommendedSeats[activeSeatPassenger]||null,activePassenger=bookingPassengers[activeSeatPassenger]||null,blockedSeats=seatSelections.filter((_,i)=>i!==activeSeatPassenger).map(s=>s?.seat).filter((v):v is string=>!!v);
function create(){setIntent({...blankIntent,seat:state?.profile.seat||'Aisle',baggage:state?.profile.baggage||23});setEditing(false);setModal('intent')}
function edit(){if(trip){setIntent(Object.fromEntries(Object.keys(blankIntent).map(k=>[k,(trip as any)[k]])) as Intent);setEditing(true);setModal('intent')}}
function nav(v:string){if(auth?.kind==='guest'&&v!=='home'){setView('home');setActive(null);return}setView(v);setActive(null);if(v==='profile')setProfileTab('personal')}
async function saveIntent(e:React.FormEvent){e.preventDefault();const d=await act(editing?'edit':'create',{intent});if(d){setModal('');setActive(d.result?.tripId||active);setView('trips');toast.success(editing?tr('Travel intent updated','Đã cập nhật nhu cầu chuyến đi'):tr('Trip thread created','Đã tạo chuyến đi'))}}
async function send(e:React.FormEvent){e.preventDefault();if(!chat.trim())return;const d=await act('chat',{text:chat});if(d)setChat('')}
async function openResultTrip(d:any,message?:string){if(d?.result?.tripId){setActive(d.result.tripId);setView('trips');if(message)toast.success(message);return true}return false}
async function sendStarterText(text:string){if(!text.trim())return null;const d=await act('starter_chat',{text});if(d){setStarterInput('');await openResultTrip(d,d.result?.monitoring?tr('Monitoring started','Đã bật theo dõi'):d.result?.checkout?tr('Opening checkout','Đang mở bước đặt vé'):undefined)}return d}
async function sendStarter(e:React.FormEvent){e.preventDefault();await sendStarterText(starterInput)}
async function starterAction(action:string,data:any={},message?:string){const d=await act(action,data);if(d?.result?.paid){setActive(null);setView('alerts');toast.success(tr('Payment completed — Travel Intent closed','Thanh toán hoàn tất — Travel Intent đã kết thúc'));return d}if(d)await openResultTrip(d,message);return d}
async function chooseStarter(action:string,data:any,_seed:string){setBookingLotusmiles(null);return starterAction(action,data)}
async function chooseStarterLotusOffer(offer:StarterSelectedOffer){const d=await starterAction('starter_select_lotus_offer',{offerId:offer.offerId,leg:'outbound'});if(d?.result?.lotusmilesRedemption)setBookingLotusmiles(d.result.lotusmilesRedemption);return d}
async function chooseStarterLotusCombo(combo:StarterRoundTripCombo){const d=await starterAction('starter_select_lotus_combo',{comboId:combo.id});if(d?.result?.lotusmilesRedemption)setBookingLotusmiles(d.result.lotusmilesRedemption);return d}
async function confirmStarter(){const d=await act('starter_confirm');if(d?.result?.tripId){setActive(d.result.tripId);setView('trips');toast.success(tr('Travel Intent created — opening your trip','Đã tạo Travel Intent — đang mở chuyến đi'))}}
async function resetStarter(){const d=await act('starter_reset');if(d)toast.success(tr('Starting conversation cleared','Đã xóa cuộc trò chuyện bắt đầu'))}
async function openNotification(n:State['notifications'][number]){await act('read');if(n.ticket){setSelectedTicket(n.ticket);setModal('ticket');setView('alerts');setActive(null);return}const target=state?.trips.find(t=>t.id===n.tripId);if(n.opportunity&&target){if(n.opportunity.itineraryId){const current=target.selectedOffer?{id:target.selectedReturnOffer?`${target.selectedOffer.offerId}__${target.selectedReturnOffer.offerId}`:target.selectedOffer.offerId,outbound:target.selectedOffer,return:target.selectedReturnOffer||null,totalPriceAUD:target.selectedOffer.totalPriceAUD+(target.selectedReturnOffer?.totalPriceAUD||0),source:'chat' as const}:null;const choices=[...(current?[current]:[]),...(target.suggestedItineraries||[]),...(target.monitoringSuggestions||[])],itinerary=choices.find(x=>x.id===n.opportunity?.itineraryId);if(itinerary){prepareTripItineraryBookingFor(target,itinerary);return}}if(n.opportunity.offerId){const direct=target.offers.find(o=>o.id===n.opportunity?.offerId);if(direct){prepareBookingFor(target,direct);return}}}if(n.tripId==='starter'&&state?.starter){setView('home');setActive(null);return}if(target){setView('trips');setActive(target.id);return}setView('alerts');setActive(null);toast.info(tr('This Travel Intent has ended. The notification is kept in your history.','Travel Intent này đã kết thúc. Thông báo vẫn được giữ lại trong lịch sử.'))}
const profileNotSaved=auth?.kind==='user'&&profileComplete===false;
function personalForm(){if(!personalProfile)return null;return <form className="panel" onSubmit={savePersonalProfile}><div className="panel-title"><div><h2>{tr('Passenger details for faster checkout','Thông tin hành khách cho lần đặt vé sau')}</h2><p>{tr('Your account is already enough to save Travel Intents, Trip Threads and preferences. Passenger identity details are optional until you choose a flight and continue to booking.','Tài khoản hiện tại đã đủ để lưu Travel Intent, Trip Thread và sở thích. Thông tin định danh hành khách là tùy chọn cho tới khi bạn chọn chuyến bay và tiếp tục đặt vé.')}</p></div><ShieldCheck className="teal"/></div><div className="info-note secure-note"><ShieldCheck size={16}/> {tr('Date of birth, home address and passport/CCCD are optional here. If you add them, they are encrypted at rest and never sent to the OpenAI recommendation explanation context. Identity documents are only needed later when the secure booking flow requires passenger verification.','Ngày sinh, địa chỉ nhà và hộ chiếu/CCCD là tùy chọn tại đây. Nếu bạn thêm, dữ liệu sẽ được mã hóa khi lưu và không được gửi vào ngữ cảnh giải thích recommendation của OpenAI. Giấy tờ định danh chỉ cần sau này khi quy trình đặt vé bảo mật yêu cầu xác minh hành khách.')}</div><div className="form-grid mt-5"><label>{tr('Full name','Họ và tên')}<input required maxLength={100} autoComplete="name" value={personalProfile.fullName} onChange={e=>setPersonalProfile({...personalProfile,fullName:e.target.value})}/></label><label>{tr('Date of birth (optional)','Ngày sinh (tùy chọn)')}<input type="date" max={new Date().toISOString().slice(0,10)} value={personalProfile.dateOfBirth} onChange={e=>setPersonalProfile({...personalProfile,dateOfBirth:e.target.value})}/></label><label>{tr('Identity document (optional)','Giấy tờ tùy thân (tùy chọn)')}<Select value={personalProfile.documentType} onValueChange={v=>setPersonalProfile({...personalProfile,documentType:v as 'passport'|'cccd'})}><SelectTrigger className="w-full"><SelectValue/></SelectTrigger><SelectContent><SelectItem value="passport">{tr('Passport','Hộ chiếu')}</SelectItem><SelectItem value="cccd">{tr('CCCD / National ID','CCCD / Căn cước')}</SelectItem></SelectContent></Select></label><label>{personalProfile.documentType==='passport'?tr('Passport number (optional)','Số hộ chiếu (tùy chọn)'):tr('CCCD / National ID number (optional)','Số CCCD / Căn cước (tùy chọn)')}<input maxLength={40} autoComplete="off" value={personalProfile.documentNumber} onChange={e=>setPersonalProfile({...personalProfile,documentNumber:e.target.value})}/></label><label>Email<input required type="email" autoComplete="email" maxLength={254} value={personalProfile.email} onChange={e=>setPersonalProfile({...personalProfile,email:e.target.value})}/></label><label>{tr('Phone number','Số điện thoại')}<input required type="tel" autoComplete="tel" maxLength={32} placeholder="+84 912 345 678" value={personalProfile.phone} onChange={e=>setPersonalProfile({...personalProfile,phone:e.target.value})}/></label></div><label className="field">{tr('Home address (optional)','Địa chỉ nhà (tùy chọn)')}<input maxLength={300} autoComplete="street-address" value={personalProfile.address} onChange={e=>setPersonalProfile({...personalProfile,address:e.target.value})}/></label><div className="profile-actions mt-5"><button className="primary" disabled={busy}>{busy?tr('Saving…','Đang lưu…'):tr('Save personal information','Lưu thông tin cá nhân')}</button></div></form>}

function preferenceLabel(d:PreferenceDimension){return ({price:tr('Lower price','Giá thấp hơn'),transit:tr('Shorter transit','Nối chuyến ngắn hơn'),journey_time:tr('Shorter total journey','Tổng hành trình ngắn hơn'),baggage:tr('Included baggage','Hành lý bao gồm'),miles:tr('Lotusmiles value','Giá trị Lotusmiles')} as Record<PreferenceDimension,string>)[d]}
function decisionProfilePanel(){if(!state)return null;const evidence=state.preferenceEvidence||[],counts=preferenceCounts(evidence),dominant=dominantPreference(evidence);return <section className="panel mt-6"><div className="panel-title"><div><h2>{tr('What LIA has learned from your choices','LIA đã học gì từ lựa chọn của bạn')}</h2><p>{tr('This is transparent preference evidence, not a hidden probability model. LIA combines reasons you explicitly save with transparent behavioural signals such as filters, selected options and completed bookings. It never turns them into a hidden booking probability.','Đây là bằng chứng sở thích minh bạch, không phải mô hình xác suất ẩn. LIA kết hợp lý do bạn chủ động lưu với tín hiệu hành vi minh bạch như bộ lọc, phương án đã chọn và booking đã hoàn tất. Hệ thống không biến chúng thành xác suất đặt vé ẩn.')}</p></div><Sparkles className="teal"/></div>{!evidence.length?<div className="info-note mt-4">{tr('No decision evidence yet. In a trip, use “Teach LIA why” on an option to save what mattered to you.','Chưa có bằng chứng quyết định. Trong một chuyến đi, hãy dùng “Cho LIA biết vì sao” trên một lựa chọn để lưu điều quan trọng với bạn.')}</div>:<><div className="row wrap mt-4">{(['price','transit','journey_time','baggage','miles'] as PreferenceDimension[]).map(d=><span className="tag" key={d}>{preferenceLabel(d)} · {counts[d]}</span>)}</div>{dominant&&!dominant.tied&&<p className="small muted mt-3">{tr(`Strongest preference signal so far: ${preferenceLabel(dominant.dimension)} (${dominant.count} choice${dominant.count===1?'':'s'}).`,`Tín hiệu sở thích mạnh nhất hiện tại: ${preferenceLabel(dominant.dimension)} (${dominant.count} lựa chọn).`)}</p>}<p className="small muted mt-3">{tr('LIA does not convert these counts into booking probabilities or causal uplift because this prototype has no authorised VNA experiment or historical conversion dataset.','LIA không chuyển các số đếm này thành xác suất đặt vé hay causal uplift vì prototype này không có dữ liệu thử nghiệm hoặc dữ liệu chuyển đổi lịch sử được Vietnam Airlines cho phép.')}</p></>}</section>}
