const recoverableBooking=state?.bookings.find(b=>b.status==='demo-review-complete'&&state.trips.some(t=>t.id===b.tripId));
const allPreferenceEvidence=state?.preferenceEvidence||[];
const dominantDecisionPreference=state?.profile.personalize?dominantPreference(allPreferenceEvidence):null;
function explicitPreferenceReason(o:Offer,t:Trip){if(!state?.profile.personalize||!dominantDecisionPreference||dominantDecisionPreference.tied)return null;if(!offerMatchesPreference(o,t,dominantDecisionPreference.dimension))return null;return tr(`${preferenceLabel(dominantDecisionPreference.dimension)} is your strongest transparent preference signal across ${dominantDecisionPreference.count} saved interaction${dominantDecisionPreference.count===1?'':'s'}.`,`${preferenceLabel(dominantDecisionPreference.dimension)} là tín hiệu sở thích minh bạch mạnh nhất qua ${dominantDecisionPreference.count} tương tác đã lưu.`)}

function openInspiration(to:string,name:string,budget:number,baggage=23,transit=4){setIntent({...blankIntent,from:'SYD',to,name,budget,baggage,transit,seat:state?.profile.seat||'No preference'});setEditing(false);setModal('intent')}
function offerReasons(o:Offer,t:Trip){if(!state)return [] as string[];const reasons:string[]=[];if(t.budget>=100000)reasons.push(tr('No hard budget limit is set for this trip','Chuyến đi này không đặt giới hạn ngân sách cứng'));else if(o.price<=t.budget)reasons.push(tr(`Within your AUD ${t.budget.toLocaleString('en-AU')} total budget`,`Nằm trong ngân sách tổng AUD ${t.budget.toLocaleString('en-AU')} của bạn`));if(o.transit<=t.transit)reasons.push(tr(`Transit stays within your ${t.transit}h limit`,`Thời gian nối chuyến nằm trong giới hạn ${t.transit} giờ`));if(o.baggage>=t.baggage)reasons.push(tr(`${o.baggage} kg baggage covers your saved trip need`,`${o.baggage} kg hành lý đáp ứng nhu cầu chuyến đi đã lưu`));if(state.profile.personalize&&state.profile.seat!=='No preference')reasons.push(tr(`Your ${state.profile.seat.toLowerCase()} seat preference will be carried into booking review`,`Ưu tiên ghế ${state.profile.seat==='Window'?'cửa sổ':'lối đi'} của bạn sẽ được chuyển sang bước xem lại đặt chỗ`));if(state.profile.family)reasons.push(tr('Family preference is included in LIA’s fit assessment','Ưu tiên đi cùng gia đình được tính trong đánh giá độ phù hợp của LIA'));if(state.profile.member){const loyalty=bestLotusmilesDemoBenefit(state.profile,{passengers:t.passengers,flexibility:o.flexibility,requestedCabin:t.requestedCabin});reasons.push(loyalty?.kind==='business-upgrade'&&loyalty.available?tr(`Your sample Lotusmiles balance can surface a Business upgrade option at ${loyalty.milesCostPerTraveller.toLocaleString('en-AU')} demo miles/person`,`Số dư Lotusmiles mẫu của bạn có thể mở thêm gợi ý nâng hạng Business ở mức ${loyalty.milesCostPerTraveller.toLocaleString('en-AU')} dặm demo/người`):tr('Your Lotusmiles member context is included; live earning/redemption eligibility will be verified at booking','Ngữ cảnh thành viên Lotusmiles được tính đến; quyền tích/đổi dặm thực sẽ được xác minh khi đặt vé'));}const learned=explicitPreferenceReason(o,t);if(learned)reasons.unshift(learned);return reasons.slice(0,4)}
function renderOffer(o:Offer){if(!trip||!state)return null;const cheapest=Math.min(...trip.offers.map(x=>x.price)),isCheapest=o.price===cheapest,isTopRanked=trip.offers[0]?.id===o.id,savedReason=(state.preferenceEvidence||[]).find(e=>e.tripId===trip.id&&e.offerId===o.id),aiPick=trip.aiRecommendation?.offerId===o.id,rec=aiPick?trip.aiRecommendation:null;return <section className={'offer-card '+(isTopRanked?'recommended':'')} key={o.id}><div className="row between"><span className="offer-label">{isTopRanked&&<Sparkles size={15}/>} {isTopRanked?tr('LIA best match · ','LIA phù hợp nhất · '):''}{o.label}{isCheapest&&<span className="tag" style={{marginLeft:8}}>{tr('Cheapest','Rẻ nhất')}</span>}</span><span className="small muted">{tripConstraintCount(o,trip)}/3 {tr('saved trip constraints met','ràng buộc chuyến đi đã lưu được đáp ứng')}</span></div><div className="offer-main"><div><div className="route large">{trip.from}<span className="flight-line"><Plane size={18}/></span>{trip.to}</div><p className="small muted">{o.flight} · {o.hours}h · {o.transit?`${o.transit}h ${tr('transit','nối chuyến')}`:tr('Nonstop','Bay thẳng')}{o.departureTime?` · ${tr('depart','khởi hành')} ${o.departureTime}`:''}</p></div><div className="price"><strong>{money(o.price)}</strong><span>{trip.passengers} {tr(trip.passengers>1?'travellers · round trip':'traveller · round trip',trip.passengers>1?'khách · khứ hồi':'khách · khứ hồi')}</span></div></div><div className="row between wrap"><div className="row wrap small"><span className="tag"><Luggage size={14}/>{o.baggage} kg {tr('included','bao gồm')}</span><span className="tag">{o.stops===0?tr('Nonstop','Bay thẳng'):`${o.stops??1} ${tr('stop','điểm dừng')}`}</span>{o.flexibility&&<span className="tag">{tr('Flex','Linh hoạt')}: {o.flexibility}</span>}<span className="tag"><Leaf size={14}/>{tr('Lotusmiles eligibility · verify','Lotusmiles · cần xác minh')}</span>{trip.budget<100000&&o.price>trip.budget&&<span className="gold-text">{tr('Above budget','Vượt ngân sách')}</span>}</div><div className="row wrap"><button className="secondary compact" type="button" onClick={()=>{setLearningOffer(o);setLearningReason('transit');setModal('learn')}}>{savedReason?tr('Update why','Cập nhật lý do'):tr('Teach LIA why','Cho LIA biết vì sao')}</button><button className="primary compact" onClick={()=>prepareBooking(o)}>{tr('Book direct with Vietnam Airlines','Đặt trực tiếp với Vietnam Airlines')} <ArrowRight size={16}/></button></div></div>{isTopRanked&&o.rankingReasons?.length?<p className="small muted mt-3"><Sparkles size={13} className="teal"/> {tr('Personalised ranking','Xếp hạng cá nhân hóa')}: {o.rankingReasons.join(' · ')}</p>:null}{isTopRanked&&state.profile.member&&<LotusmilesSuggestionCard profile={state.profile} passengers={trip.passengers} baseId={o.id} basePrice={o.price} flexibility={o.flexibility} directions={2} busy={busy} onChoose={()=>{const redemption=buildLotusmilesBusinessUpgrade(state.profile,{passengers:trip.passengers,flexibility:o.flexibility,baseItineraryId:o.id,directions:2});if(redemption)prepareBookingFor(trip,o,redemption)}}/>}{savedReason&&<p className="small muted mt-3"><Sparkles size={13} className="teal"/> {tr('Saved decision reason','Lý do quyết định đã lưu')}: {preferenceLabel(savedReason.dimension)}</p>}{rec&&<div className="info-note mt-4"><div><strong>{tr('Why LIA selected this candidate','Vì sao LIA chọn phương án này')}</strong><p className="small mt-2">{rec.summary}</p><ul className="benefits">{rec.reasons.map((r,i)=><li key={i}><Check/> {r}</li>)}</ul>{rec.tradeoffs.length>0&&<><strong>{tr('Trade-offs LIA identified','Trade-off LIA xác định')}</strong><ul className="benefits">{rec.tradeoffs.map((r,i)=><li key={i}><ArrowRight size={14}/> {r}</li>)}</ul></>}<p className="small muted mt-3">{tr('The model was only allowed to choose an ID from the retrieved synthetic records. The backend rejects an unknown ID.','Model chỉ được phép chọn ID từ các record giả lập đã truy xuất. Backend sẽ từ chối ID không tồn tại.')}</p></div></div>}<p className="small muted mt-3">{tr('Synthetic demo record — not a live Vietnam Airlines fare or inventory record.','Record giả lập phục vụ demo — không phải giá vé hoặc tồn chỗ trực tiếp của Vietnam Airlines.')}</p></section>}
